def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            if color == background or len(component) != 1:
                continue

            y, x = component[0]
            best_color = None
            best_score = (-1, -1)

            # Replace the isolated mark with the color that best completes
            # a solid rectangular patch around it.
            for top in range(max(0, y - 7), y + 1):
                for bottom in range(y, min(h, y + 8)):
                    for left in range(max(0, x - 7), x + 1):
                        for right in range(x, min(w, x + 8)):
                            area = (bottom - top + 1) * (right - left + 1)
                            if area < 2:
                                continue
                            counts = Counter(
                                grid[yy][xx]
                                for yy in range(top, bottom + 1)
                                for xx in range(left, right + 1)
                                if (yy, xx) != (y, x)
                            )
                            if len(counts) == 1:
                                candidate = next(iter(counts))
                                score = (area, min(bottom - top + 1, right - left + 1))
                                if score > best_score:
                                    best_score = score
                                    best_color = candidate

            if best_color is None:
                nearby = Counter(
                    grid[yy][xx]
                    for yy in range(max(0, y - 2), min(h, y + 3))
                    for xx in range(max(0, x - 2), min(w, x + 3))
                    if (yy, xx) != (y, x)
                )
                best_color = nearby.most_common(1)[0][0] if nearby else background

            out[y][x] = best_color

    return out
